public class OwnedPrimitiveReflection {
    public interface Contract {}
    public abstract class AbstractValue {}
    public class ConcreteValue {}

    public static Map<String,Object> construct(Type target) {
        Map<String,Object> row = new Map<String,Object>();
        try {
            Object value = target.newInstance();
            row.put('state', 'value');
            row.put('value', String.valueOf(value));
            row.put('isString', value instanceof String);
            row.put('isStringList', value instanceof List<String>);
            row.put('isConcrete', value instanceof ConcreteValue);
        } catch (Exception problem) {
            row.put('state', 'exception');
            row.put('type', problem.getTypeName());
            row.put('message', problem.getMessage());
        }
        return row;
    }
}

