@IsTest
private class PrimitiveReflectionObservation {
    private static void emit(String cell, Map<String,Object> row) {
        row.put('cell',cell);
        row.put('sourceApi','63.0');
        row.put('callerApi','63.0');
        System.assertEquals('capture', 'PRIMITIVE_REFLECTION_OBSERVATION ' + JSON.serialize(row));
    }
    @IsTest static void integerLiteral() { emit('integerLiteral', OwnedPrimitiveReflection.construct(Integer.class)); }
    @IsTest static void integerQualified() { emit('integerQualified', OwnedPrimitiveReflection.construct(System.Integer.class)); }
    @IsTest static void integerLookup() { emit('integerLookup', OwnedPrimitiveReflection.construct(Type.forName('Integer'))); }
    @IsTest static void stringLiteral() { emit('stringLiteral', OwnedPrimitiveReflection.construct(String.class)); }
    @IsTest static void listLiteral() { emit('listLiteral', OwnedPrimitiveReflection.construct(List<String>.class)); }
    @IsTest static void interfaceLiteral() { emit('interfaceLiteral', OwnedPrimitiveReflection.construct(OwnedPrimitiveReflection.Contract.class)); }
    @IsTest static void abstractLiteral() { emit('abstractLiteral', OwnedPrimitiveReflection.construct(OwnedPrimitiveReflection.AbstractValue.class)); }
    @IsTest static void concreteLiteral() { emit('concreteLiteral', OwnedPrimitiveReflection.construct(OwnedPrimitiveReflection.ConcreteValue.class)); }
    @IsTest static void emptyString() {
        Object value = '';
        emit('emptyString', new Map<String,Object>{'state'=>'value', 'value'=>String.valueOf(value), 'isString'=>value instanceof String, 'isStringList'=>value instanceof List<String>, 'isConcrete'=>value instanceof OwnedPrimitiveReflection.ConcreteValue});
    }
}

